static NSString *RAMText(NSNumber *bytes,BOOL known){return known?[NSString stringWithFormat:@"≈%.1f МБ",bytes.doubleValue/1000000.0]:@"нет данных";}
@interface RPCatalogCell : UITableViewCell
@property(nonatomic,strong) UIButton *infoButton;
@property(nonatomic,strong) UILabel *nameLabel;
@end
@implementation RPCatalogCell
- (instancetype)initWithStyle:(UITableViewCellStyle)style reuseIdentifier:(NSString*)rid {
 if((self=[super initWithStyle:style reuseIdentifier:rid])){
  _infoButton=[UIButton buttonWithType:UIButtonTypeSystem];[_infoButton setImage:[UIImage systemImageNamed:@"info.circle"] forState:UIControlStateNormal];_infoButton.tintColor=UIColor.systemBlueColor;_infoButton.translatesAutoresizingMaskIntoConstraints=NO;
  _nameLabel=[[UILabel alloc] init];_nameLabel.font=[UIFont systemFontOfSize:13 weight:UIFontWeightMedium];_nameLabel.numberOfLines=2;_nameLabel.translatesAutoresizingMaskIntoConstraints=NO;
  [self.contentView addSubview:_infoButton];[self.contentView addSubview:_nameLabel];
  [NSLayoutConstraint activateConstraints:@[[_infoButton.leadingAnchor constraintEqualToAnchor:self.contentView.leadingAnchor constant:8],[_infoButton.widthAnchor constraintEqualToConstant:36],[_infoButton.topAnchor constraintEqualToAnchor:self.contentView.topAnchor],[_infoButton.bottomAnchor constraintEqualToAnchor:self.contentView.bottomAnchor],[_nameLabel.leadingAnchor constraintEqualToAnchor:_infoButton.trailingAnchor constant:4],[_nameLabel.trailingAnchor constraintEqualToAnchor:self.contentView.trailingAnchor constant:-8],[_nameLabel.centerYAnchor constraintEqualToAnchor:self.contentView.centerYAnchor]]];
  UISwitch *sw=[[UISwitch alloc] init];sw.on=NO;sw.enabled=NO;self.accessoryView=sw;self.selectionStyle=UITableViewCellSelectionStyleNone;
 }return self;
}
@end
