@implementation RPProtectedController
- (instancetype)init {if((self=[super init])){__weak RPProtectedController *w=self;notify_register_dispatch("com.ratush.daemonpresets.changed",&_memoryToken,dispatch_get_main_queue(),^(int t){[w.tableView reloadData];});}return self;}
- (void)dealloc {notify_cancel(_memoryToken);}
- (void)viewWillAppear:(BOOL)animated {[super viewWillAppear:animated];Command(@"query");[self.tableView reloadData];}
- (void)viewDidLoad {[super viewDidLoad];self.tableView=[[UITableView alloc] initWithFrame:self.view.bounds style:UITableViewStyleInsetGrouped];self.tableView.autoresizingMask=UIViewAutoresizingFlexibleWidth|UIViewAutoresizingFlexibleHeight;self.tableView.delegate=self;self.tableView.dataSource=self;[self.view addSubview:self.tableView];self.title=@"Критические (неотключаемые)";self.tableView.rowHeight=56;self.tableView.estimatedRowHeight=56;UISearchBar *search=[[UISearchBar alloc] init];search.placeholder=@"Поиск по имени службы";search.delegate=self;[search sizeToFit];self.tableView.tableHeaderView=search;UIActivityIndicatorView *spinner=[[UIActivityIndicatorView alloc] initWithActivityIndicatorStyle:UIActivityIndicatorViewStyleMedium];[spinner startAnimating];self.tableView.backgroundView=spinner;
 dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY,0),^{@autoreleasepool{NSMutableSet *reviewed=[NSMutableSet set];for(NSDictionary *j in Catalog()[@"jobs"])[reviewed addObject:j[@"label"]];NSDictionary *critical=@{@"com.apple.backboardd":@"Ввод и графическая оболочка",@"com.apple.SpringBoard":@"Домашний экран",@"com.apple.cfprefsd.xpc.daemon":@"Системные настройки",@"com.apple.mobile.lockdown":@"Подключение и доверие устройства",@"com.apple.securityd":@"Связка ключей и безопасность",@"com.apple.trustd":@"Проверка сертификатов",@"com.apple.runningboardd":@"Жизненный цикл приложений",@"com.apple.assertiond":@"Жизненный цикл приложений",@"com.apple.notifyd":@"Уведомления процессов",@"com.apple.configd":@"Конфигурация сети",@"com.apple.mDNSResponder":@"Разрешение сетевых имён",@"com.apple.CommCenter":@"Сотовая связь",@"com.apple.wifid":@"Wi-Fi",@"com.apple.powerd":@"Питание и сон",@"com.apple.watchdogd":@"Контроль работоспособности",@"com.apple.logd":@"Системный журнал",@"com.apple.installd":@"Установка приложений",@"com.apple.lsd":@"Регистрация приложений",@"com.apple.tccd.system":@"Разрешения приложений",@"com.apple.nehelper":@"Сетевые расширения",@"com.apple.nesessionmanager":@"VPN и сетевые сеансы",@"com.ratush.daemonpresetsd":@"Управление этим твиком"};NSMutableDictionary *unique=[NSMutableDictionary dictionary];NSFileManager *fm=NSFileManager.defaultManager;
 for(NSString *dir in @[@"/System/Library/LaunchDaemons",@"/System/Library/LaunchAgents",@"/var/jb/Library/LaunchDaemons",@"/var/jb/Library/LaunchAgents"])for(NSString *file in [fm contentsOfDirectoryAtPath:dir error:nil]){@autoreleasepool{if(![file.pathExtension isEqual:@"plist"])continue;NSString *path=[dir stringByAppendingPathComponent:file];NSDictionary *d=[NSDictionary dictionaryWithContentsOfFile:path];NSString *label=d[@"Label"];if(![label isKindOfClass:NSString.class] || [reviewed containsObject:label])continue;NSString *role=critical[label];BOOL protected=role!=nil || [label containsString:@"sshd"] || [label containsString:@"jailbreak"] || [label containsString:@"dopamine"];NSString *note=protected?[NSString stringWithFormat:@"Критическая / защищённая: %@. Отключение заблокировано.",role?:@"доступ и работа jailbreak"]:@"Не проверена для отключения. Переключатель заблокирован; это не утверждение о критичности.";unique[label]=@{@"label":label,@"path":path,@"note":note,@"critical":@(protected)};}}
 NSArray *rows=[unique.allValues sortedArrayUsingComparator:^NSComparisonResult(NSDictionary *x,NSDictionary *y){if([x[@"critical"] boolValue]!=[y[@"critical"] boolValue])return [x[@"critical"] boolValue]?NSOrderedAscending:NSOrderedDescending;return [x[@"label"] localizedCaseInsensitiveCompare:y[@"label"]];}];dispatch_async(dispatch_get_main_queue(),^{self.inventory=rows;self.filtered=rows;self.tableView.backgroundView=nil;self.title=[NSString stringWithFormat:@"Критические (%lu демонов)",(unsigned long)rows.count];[self.tableView reloadData];});}});}
- (void)searchBar:(UISearchBar*)searchBar textDidChange:(NSString*)text {if(!text.length)self.filtered=self.inventory;else {NSMutableArray *a=[NSMutableArray array];for(NSDictionary *j in self.inventory)if([j[@"label"] localizedCaseInsensitiveContainsString:text])[a addObject:j];self.filtered=a;}[self.tableView reloadData];}
- (NSInteger)tableView:(UITableView*)tableView numberOfRowsInSection:(NSInteger)section {return self.filtered.count;}
- (UITableViewCell*)tableView:(UITableView*)tableView cellForRowAtIndexPath:(NSIndexPath*)path {
 RPCatalogCell *cell=[tableView dequeueReusableCellWithIdentifier:@"locked"];if(!cell)cell=[[RPCatalogCell alloc] initWithStyle:UITableViewCellStyleDefault reuseIdentifier:@"locked"];
 NSDictionary *j=self.filtered[path.row],*mem=Status()[@"ramByLabel"][j[@"label"]];cell.nameLabel.text=[NSString stringWithFormat:@"%@\nRAM: %@",j[@"label"],RAMText(mem[@"bytes"],[mem[@"known"] boolValue])];cell.infoButton.accessibilityIdentifier=j[@"label"];cell.infoButton.accessibilityLabel=[@"Информация о " stringByAppendingString:j[@"label"]];[cell.infoButton removeTarget:nil action:NULL forControlEvents:UIControlEventTouchUpInside];[cell.infoButton addTarget:self action:@selector(infoPressed:) forControlEvents:UIControlEventTouchUpInside];return cell;
}
